function TemperatureConverter() {
  const [celsius, setCelsius] = useState(0);
  const fahrenheit = celsius * 9 / 5 + 32;

  return (
    <>
      <input
        type="number"
        value={celsius}
        onChange={(e) => setCelsius(Number(e.target.value))}
      />
      <input
        type="number"
        value={fahrenheit}
        onChange={(e) => setCelsius((Number(e.target.value) - 32) * 5 / 9)}
      />
    </>
  );
}
